import{b as r,O as o,g as d,j as a,d as t}from"./chunks/framework.DcaUmd3X.js";const b=JSON.parse('{"title":"8 步走通第一个压测","description":"","frontmatter":{},"headers":[],"relativePath":"performance/jmeter/first-script/index.md","filePath":"性能测试/1.Jmeter/03.第一个压测脚本.md","lastUpdated":1781755252000}'),n={name:"performance/jmeter/first-script/index.md"};function s(l,e,p,i,h,u){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="_8-步走通第一个压测" tabindex="-1">8 步走通第一个压测 <a class="header-anchor" href="#_8-步走通第一个压测" aria-label="Permalink to &quot;8 步走通第一个压测&quot;">​</a></h1><blockquote><p>跟着操作，从零搭出一个能跑的压测脚本。掌握线程组 (Thread Group)、HTTP 请求 (HTTP Request)、Token 关联 (Correlation)、监听器 (Listener) 四大核心操作。</p></blockquote><h2 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to &quot;准备工作&quot;">​</a></h2><p>启动 JMeter，确保界面是中文（菜单栏 → Options → Choose Language → 中文简体）。</p><p>你会看到一个空的 Test Plan，接下来每一步都是<strong>右键 → 添加</strong>。</p><h2 id="步骤-1-创建线程组-thread-group" tabindex="-1">步骤 1：创建线程组 (Thread Group) <a class="header-anchor" href="#步骤-1-创建线程组-thread-group" aria-label="Permalink to &quot;步骤 1：创建线程组 (Thread Group)&quot;">​</a></h2><p>右键 <strong>Test Plan</strong> → 添加 → 线程（用户）→ <strong>线程组 (Thread Group)</strong></p><table tabindex="0"><thead><tr><th>参数</th><th style="text-align:center;">值</th><th>含义</th></tr></thead><tbody><tr><td>名称</td><td style="text-align:center;">商城压力测试</td><td>好名字让脚本一目了然</td></tr><tr><td>线程数</td><td style="text-align:center;">50</td><td>模拟 50 个并发用户</td></tr><tr><td>Ramp-Up 时间（秒）</td><td style="text-align:center;">10</td><td>10 秒内逐步启动完，每秒加 5 个</td></tr><tr><td>循环次数</td><td style="text-align:center;">3</td><td>每个用户跑 3 轮，共 150 笔请求</td></tr></tbody></table><blockquote><p><strong>为什么不是&quot;永远&quot;？</strong> 第一次跑用固定次数，确认脚本没问题再改成永远。</p></blockquote><h2 id="步骤-2-加全局请求头" tabindex="-1">步骤 2：加全局请求头 <a class="header-anchor" href="#步骤-2-加全局请求头" aria-label="Permalink to &quot;步骤 2：加全局请求头&quot;">​</a></h2><p>右键 线程组 → 添加 → 配置元件 → <strong>HTTP 信息头管理器 (HTTP Header Manager)</strong></p><table tabindex="0"><thead><tr><th>名称</th><th>值</th></tr></thead><tbody><tr><td>Content-Type</td><td>application/json</td></tr></tbody></table><blockquote><p><strong>为什么放线程组下而不是某个请求下？</strong> 回顾第一章的作用域口诀——&quot;父管子&quot;。放线程组下，组里所有请求都自动带上这个头。</p></blockquote><h2 id="步骤-3-创建登录请求" tabindex="-1">步骤 3：创建登录请求 <a class="header-anchor" href="#步骤-3-创建登录请求" aria-label="Permalink to &quot;步骤 3：创建登录请求&quot;">​</a></h2><p>右键 线程组 → 添加 → 取样器 → <strong>HTTP 请求 (HTTP Request)</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>名称</td><td>登录</td></tr><tr><td>协议</td><td>http</td></tr><tr><td>服务器名称或 IP</td><td>localhost</td></tr><tr><td>端口号</td><td>8080</td></tr><tr><td>HTTP 方法</td><td>POST</td></tr><tr><td>路径</td><td>/api/login</td></tr><tr><td>消息体数据 (Body Data)</td><td><code>{&quot;username&quot;:&quot;admin&quot;,&quot;password&quot;:&quot;admin123&quot;}</code></td></tr></tbody></table><blockquote><p><strong>消息体数据</strong>在面板底部，是一个大文本框，<strong>不是上面那个参数表</strong>。很多新手在这里找了半天——参数表里填的是 GET 请求的 Query String，POST 的 JSON 要填在下面的消息体数据里。</p></blockquote><h2 id="步骤-4-提取-token-关联" tabindex="-1">步骤 4：提取 Token（关联） <a class="header-anchor" href="#步骤-4-提取-token-关联" aria-label="Permalink to &quot;步骤 4：提取 Token（关联）&quot;">​</a></h2><p>这是整个脚本最关键的一步——从登录响应里取出 token，后面的请求都要用。</p><p>右键「登录」请求 → 添加 → 后置处理器 → <strong>JSON 提取器 (JSON Extractor)</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>名称</td><td>提取 Token</td></tr><tr><td>创建的变量名称</td><td>token</td></tr><tr><td>JSON Path 表达式</td><td>$.token</td></tr><tr><td>默认值</td><td>NOT_FOUND</td></tr></tbody></table><blockquote><p><strong>为什么放登录请求下？</strong> 作用域——只对登录这一个请求生效，提取登录返回的 token。</p></blockquote><p><strong>关联三步走</strong>，以后每次遇到动态值都按这个套路：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 找到动态值在哪 → 看登录响应，里面有 token 字段</span></span>\n<span class="line"><span>2. 加提取器     → JSON 提取器，表达式 $.token，变量名 token</span></span>\n<span class="line"><span>3. 后面引用     → 用 ${token} 代替硬编码的值</span></span></code></pre></div><blockquote><p><code>$.token</code> 表示取 JSON 根下的 token 字段。如果 token 在 <code>data.token</code>，表达式就是 <code>$.data.token</code>。</p></blockquote><h2 id="步骤-5-加认证请求头" tabindex="-1">步骤 5：加认证请求头 <a class="header-anchor" href="#步骤-5-加认证请求头" aria-label="Permalink to &quot;步骤 5：加认证请求头&quot;">​</a></h2><p>现在 token 已经存到变量 <code>${token}</code> 里了，但后续请求还不知道要带它。</p><p>右键 线程组 → 添加 → 配置元件 → <strong>HTTP 信息头管理器 (HTTP Header Manager)</strong></p>',28),t("table",{tabindex:"0"},[t("thead",null,[t("tr",null,[t("th",null,"名称"),t("th",null,"值")])]),t("tbody",null,[t("tr",null,[t("td",null,"名称"),t("td",null,"认证头")]),t("tr",null,[t("td",null,"Authorization"),t("td",{token:""},"Bearer $")])])],-1),a(`<blockquote><p>现在你有两个 Header Manager 了：一个管 Content-Type，一个管 Authorization。JMeter 会自动合并它们。</p></blockquote><h2 id="步骤-6-添加业务请求" tabindex="-1">步骤 6：添加业务请求 <a class="header-anchor" href="#步骤-6-添加业务请求" aria-label="Permalink to &quot;步骤 6：添加业务请求&quot;">​</a></h2><p>右键 线程组 → 添加 → 取样器 → <strong>HTTP 请求</strong>，依次创建四个请求。这四个请求会自动带上登录后的 token。</p><p><strong>请求 1：获取商品列表</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>名称</td><td>获取商品列表</td></tr><tr><td>HTTP 方法</td><td>GET</td></tr><tr><td>路径</td><td>/api/products</td></tr></tbody></table><p><strong>请求 2：获取订单列表</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>名称</td><td>获取订单列表</td></tr><tr><td>HTTP 方法</td><td>GET</td></tr><tr><td>路径</td><td>/api/orders</td></tr></tbody></table><p><strong>请求 3：创建订单</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>名称</td><td>创建订单</td></tr><tr><td>HTTP 方法</td><td>POST</td></tr><tr><td>路径</td><td>/api/orders</td></tr><tr><td>消息体数据</td><td><code>{&quot;productId&quot;:1,&quot;quantity&quot;:2,&quot;orderNo&quot;:&quot;\${__time(yyyyMMddHHmmss)}&quot;}</code></td></tr></tbody></table><blockquote><p>消息体数据同样在面板底部的大文本框，别填到参数表里。 <code>\${__time(yyyyMMddHHmmss)}</code> 是 JMeter 内置的时间函数，每执行一次生成不同时间戳。压测时同时创建多条订单，订单号必须唯一，否则会报重复错误。</p></blockquote><p><strong>请求 4：获取用户信息</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>名称</td><td>获取用户信息</td></tr><tr><td>HTTP 方法</td><td>GET</td></tr><tr><td>路径</td><td>/api/user/profile</td></tr></tbody></table><h2 id="步骤-7-加监听器-看结果" tabindex="-1">步骤 7：加监听器（看结果） <a class="header-anchor" href="#步骤-7-加监听器-看结果" aria-label="Permalink to &quot;步骤 7：加监听器（看结果）&quot;">​</a></h2><p>右键 线程组 → 添加 → 监听器，加这两个就够了：</p><table tabindex="0"><thead><tr><th>监听器</th><th>什么时候用</th></tr></thead><tbody><tr><td><strong>察看结果树 (View Results Tree)</strong></td><td>调试时开，看每个请求的详细请求/响应。<strong>正式压测必须关掉</strong>（吃内存）</td></tr><tr><td><strong>汇总报告 (Summary Report)</strong></td><td>正式压测用，看平均、最快、最慢、错误率、吞吐量</td></tr></tbody></table><h2 id="步骤-8-保存并运行" tabindex="-1">步骤 8：保存并运行 <a class="header-anchor" href="#步骤-8-保存并运行" aria-label="Permalink to &quot;步骤 8：保存并运行&quot;">​</a></h2><ol><li><code>Cmd+S</code> 保存，文件名随意，比如 <code>demo-jmeter.jmx</code></li><li>点工具栏绿色 ▶ 按钮运行</li><li>跑完后看汇总报告的数据</li></ol><p><strong>调试技巧</strong>：第一次跑建议把线程数改成 <strong>1</strong>、循环次数 <strong>1</strong>。先用察看结果树确认每个请求都返回正常（状态码 200，响应里有正确数据），脚本调通了再改回 50 线程 × 3 次正式压。</p><hr><h2 id="你的脚本现在长这样" tabindex="-1">你的脚本现在长这样 <a class="header-anchor" href="#你的脚本现在长这样" aria-label="Permalink to &quot;你的脚本现在长这样&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Test Plan</span></span>
<span class="line"><span>  └── 线程组 (Thread Group)（50用户 × 3次循环）</span></span>
<span class="line"><span>        ├── HTTP 信息头管理器 (HTTP Header Manager)     Content-Type: application/json</span></span>
<span class="line"><span>        ├── HTTP 信息头管理器 (HTTP Header Manager)     Authorization: Bearer \${token}</span></span>
<span class="line"><span>        ├── 🔵 登录 (HTTP Request)                     POST /api/login</span></span>
<span class="line"><span>        │      └── JSON 提取器 (JSON Extractor)         提取 token ← 只对登录生效</span></span>
<span class="line"><span>        ├── 🔵 获取商品列表 (HTTP Request)              GET  /api/products</span></span>
<span class="line"><span>        ├── 🔵 获取订单列表 (HTTP Request)              GET  /api/orders</span></span>
<span class="line"><span>        ├── 🔵 创建订单 (HTTP Request)                  POST /api/orders</span></span>
<span class="line"><span>        ├── 🔵 获取用户信息 (HTTP Request)              GET  /api/user/profile</span></span>
<span class="line"><span>        ├── 察看结果树 (View Results Tree)              调试用</span></span>
<span class="line"><span>        └── 汇总报告 (Summary Report)                   看统计</span></span></code></pre></div><p>对照第一章的心法检查一下：</p><ul><li><strong>执行顺序</strong>：每个请求前 → Header Manager（配）先执行 → 然后 HTTP 请求（取）→ JSON 提取器（后）→ 最后监听器（听）</li><li><strong>作用域</strong>：两个 Header Manager 挂线程组下 → 对所有请求生效；JSON 提取器挂登录下 → 只对登录生效</li></ul><p>完全符合。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一章你学会了压测脚本的标准搭建流程：</p><ul><li><strong>线程组 (Thread Group)</strong>：定义并发用户数和运行方式</li><li><strong>HTTP 请求 (HTTP Request)</strong>：协议 + 地址 + 路径 + 方法 = 一个请求</li><li><strong>关联 (Correlation)</strong>：JSON 提取器 (JSON Extractor) → 变量 → <code>\${变量名}</code> 引用，三步走</li><li><strong>监听器 (Listener)</strong>：调试用察看结果树 (View Results Tree)，压测用汇总报告 (Summary Report)</li><li><strong>调试习惯</strong>：先 1 线程跑通，再放大压测</li></ul><p>这 8 步是 JMeter 最核心的操作路径，以后任何压测脚本都是这个模板的变体。下一章逐个拆解每种元件。</p>`,28)])])}const T=r(n,[["render",s]]);export{b as __pageData,T as default};
